import { VERSION_SQL } from "./sql/version.sql.js";
// src/vendor/postgres-meta/lib/PostgresMetaVersion.ts
var PostgresMetaVersion = class {
	constructor(query) {
		this.query = query;
	}
	async retrieve() {
		const { data, error } = await this.query(VERSION_SQL());
		if (error) return {
			data,
			error
		};
		return {
			data: data[0],
			error
		};
	}
};
export { PostgresMetaVersion as default };
